public class METEcoResAttributeRemove extends RunBaseBatch implements BatchRetryable
{
    NoYesId      estimateOnly;

    DialogField  dlgEstimateOnly;


    EcoResAttribute callerEcoResAttribute;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        estimateOnly
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();
    ;
    dlgEstimateOnly  = dialog.addFieldValue(extendedtypestr(NoYesId), estimateOnly, "Estimate only", "Get the number of linked records without delete");

    return dialog;
}

public boolean getFromDialog()
{
    ;
    estimateOnly   = dlgEstimateOnly.value();

    return super();
}

public NoYesId parmEstimateOnly(NoYesId _estimateOnly = estimateOnly)
{
    estimateOnly = _estimateOnly;
    return estimateOnly;
}

public EcoResAttribute parmCallerEcoResAttribute(EcoResAttribute _callerEcoResAttribute = callerEcoResAttribute)
{
    callerEcoResAttribute = _callerEcoResAttribute;
    return callerEcoResAttribute;
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = _packedClass;
            break;
        default:
            return false;
    }
    return true;
}

public void run()
{
    EcoResAttributeGroupAttribute   attributeGroupAttribute;
    EcoResValue                     ecoResValue;
    EcoResAttributeValue            attributeValue, attributeValueJoin;
    EcoResAttribute                 ecoResAttributeUpdate;
    GUPPricingAttributeLink         pricingAttributeLink;
    RecId                           attributeRecId = callerEcoResAttribute.RecId;     
    int                             countAttributeGroupAttribute;
    int                             countEcoResValue;
    int                             countAttributeValue;
    int                             countAttributeLink;

    if (attributeRecId == 0)
    {
        error("Please specify the Attribute RecId to process.");
        return;
    }

    ttsbegin;

    // Process EcoResAttributeGroupAttribute
    select count(RecId) from attributeGroupAttribute
        where attributeGroupAttribute.Attribute == attributeRecId;

    countAttributeGroupAttribute = attributeGroupAttribute.RecId;

    if (!estimateOnly && countAttributeGroupAttribute > 0)
    {
        delete_from attributeGroupAttribute
            where attributeGroupAttribute.Attribute == attributeRecId;
    }

    info(strFmt("EcoResAttributeGroupAttribute: %1 records %2",
                                                countAttributeGroupAttribute,
                                                estimateOnly ? "will be deleted" : "deleted"));

    // Process EcoResValue 
    select count(RecId) from ecoResValue
        exists join attributeValueJoin
        where attributeValueJoin.Value == ecoResValue.RecId
            && attributeValueJoin.Attribute == attributeRecId;

    countEcoResValue = ecoResValue.RecId;

    if (!estimateOnly && countEcoResValue > 0)
    {
        delete_from ecoResValue
            exists join attributeValueJoin
            where attributeValueJoin.Value == ecoResValue.RecId
                && attributeValueJoin.Attribute == attributeRecId;
    }

    info(strFmt("EcoResValue: %1 records %2",
                                countEcoResValue,
                                estimateOnly ? "will be deleted" : "deleted"));

    // Process GUPPricingAttributeLink
    select count(RecId) from pricingAttributeLink
        where pricingAttributeLink.AttributeName == callerEcoResAttribute.Name
           && pricingAttributeLink.TypeName == callerEcoResAttribute.getActualAttributeType().Name
           && pricingAttributeLink.PriceAttributeClassId == classNum(GUPPricingAttributeEcoResAttribute);

    countAttributeLink = pricingAttributeLink.RecId;

    if (!estimateOnly && countAttributeLink > 0)
    {
        delete_from pricingAttributeLink
            where pricingAttributeLink.AttributeName == callerEcoResAttribute.Name
               && pricingAttributeLink.TypeName == callerEcoResAttribute.getActualAttributeType().Name
               && pricingAttributeLink.PriceAttributeClassId == classNum(GUPPricingAttributeEcoResAttribute);
    }

    info(strFmt("GUPPricingAttributeLink: %1 records %2",
                                            countAttributeLink,
                                            estimateOnly ? "will be deleted" : "deleted"));

    // Process EcoResAttributeValue
    select count(RecId) from attributeValue
        where attributeValue.Attribute == attributeRecId;

        countAttributeValue = attributeValue.RecId;

    if (!estimateOnly && countAttributeValue > 0)
    {
        delete_from attributeValue
            where attributeValue.Attribute == attributeRecId;
    }

    // Process EcoResAttribute
    ecoResAttributeUpdate = EcoResAttribute::find(attributeRecId, true);

    if (!estimateOnly)
    {
        METGlobal::validateDeleteRecordCheck(ecoResAttributeUpdate);

        ecoResAttributeUpdate.delete();
    }

    info(strFmt("EcoResAttributeGroupAttribute: %1 records %2",
                                                countAttributeGroupAttribute,
                                                estimateOnly ? "will be deleted" : "deleted"));

    info(strFmt("EcoResAttributeValue: %1 records %2",
                                countAttributeValue,
                                estimateOnly ? "will be deleted" : "deleted"));

    info(strFmt("%1 - %2 - %3 - Total records: %4", estimateOnly ? "Estimation mode" : "Deletion completed",
                                            callerEcoResAttribute.Name,
                                            callerEcoResAttribute.RecId,
                                            countAttributeGroupAttribute + countEcoResValue + countAttributeValue));

    ttscommit;

    // Refresh the data source in the caller form
    METGlobal::dsResearch(callerEcoResAttribute, NoYes::No);
}

public static METEcoResAttributeRemove construct()
{
    return new METEcoResAttributeRemove();
}

static ClassDescription description()
{
    return "Remove attribute with linked values";
}

public static void main(Args _args)
{
    METEcoResAttributeRemove    runObject = METEcoResAttributeRemove::construct();
    QueryBuildDataSource  qbds;
    ;

    if (_args.dataset() != tablenum(EcoResAttribute))
    {
        throw error(Error::missingRecord(funcname()));
    }

    runObject.parmCallerEcoResAttribute(_args.record());

    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
